function goSSJ(u,why){if(u.ssj||u.dead)return;u.ssj=true;transformFx(u);tfMsg(u,u.D.name+' devient Super Saiyan : '+why,'#ffd23a');}
function goBlue(u,why){if(u.sblue||u.dead)return;u.ssj=true;u.sblue=true;fxRing(u.x,u.y,'#4ad8ff',100);part('flash',u.x,u.y-20,0,0,.5,130,'#4ad8ff');shake(5);tfMsg(u,u.D.name+' passe Super Saiyan Blue : '+why,'#4ad8ff');}
function uiReady(u){if(!u.sblue)return false;let n=0;for(const e of ents)if(!e.dead&&e.isU&&foe(e.side,u.side)&&hyp(e.x-u.x,e.y-u.y)<230)n++;
  return n>=5||!!(u.target&&!u.target.dead&&u.target.D&&u.target.D.legend);}
const TF_TXT={ssj:'Super Saiyan : quand un héros allié tombe à proximité (colère), ou au combat dès le rang 2.',blue:'Super Saiyan Blue (Dieu Dragon débloqué) : déjà Super Saiyan, rang 2, face à un héros ou une légende ennemie.'};
